Method.Implementation:
	Set usrNm = $username
	set files = ""
	set SelectedIntfiles = ""

	if ( (Selectedfiles = "") || (comment = "") )
	{
		Quit $$$ERROR(6484, "FileNames and comment are empty")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)

		if ( fileNm '= "")
		{
		   SET files = files _ " " _ fileNm 
	    }
	    else
	    {
		    continue
	    }
	    Do ..AddDirectoriesToSvn(fileNm, passwd)

        // Get latest from Ensemble DB 

	    &sql(SELECT  InternalName INTO :InternalName FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:fileNm)

	    IF SQLCODE = 0 
        { 
	        Set sc=$$Export^%occXMLExport(fileNm,"-d /diffexport",InternalName)
	        if ( ($$$ISOK(sc)) &&  (##class(%Library.File).Exists(fileNm)) )
	        {
	          set SelectedIntfiles = SelectedIntfiles _ "," _ InternalName
         	  Do ##class(ITFCOMMON.Utility).WriteToFile("CheckinFiles: " _ $NAMESPACE _ " " _ fileNm _" -d /diffexport " _InternalName)
	          Do ..AddToSvn(fileNm, 0, passwd)	
	        }
	        else
	        {
		          Do ##class(ITFCOMMON.Utility).WriteToFile("CheckinFiles: file does not exits: " _ fileNm _" -d /diffexport " _InternalName)

	        }
        }
	}

	if (files '= "" )
    {

	    Set cmd = $$$SVNCOMMIT _ " --username " _ usrNm _ " --password " _ passwd  _ " -m """ _ comment _ """ " _ files  ; a non-recursive commit (-N)
	    Set stat = $ZF(-1, cmd)

        Do ##class(ITFCOMMON.Utility).WriteToFile("CheckinFiles: commit " _ stat)

		if stat '= 0
		{
		  Do ##class(ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ files)
		  Quit $$$ERROR(5880, "SVN commit error")
		}

    }
    For I=1:1:$L(SelectedIntfiles,",")
	{
		Set InternalName = $P(SelectedIntfiles,",",I)

		if ( InternalName '= "")
		{
          Do ..AddToSourceControl(InternalName)
		}
	}
     Quit $$$OK

Set usrNm = $username
set stat = $$$ERROR(9100, "Could not add")
SET fullPath = $$$USRBASEDIR _ $username _ $$$SVNBASEDIR _ $$$SVNTRUNK
set svnPath=$REPLACE(fName, fullPath, "")
Do ##class(ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn " _ fullPath _ " = " _svnPath) 
SET fileParts = $Length(svnPath, "/")
// Check if directories from SVN BASE exists or not
FOR ind=1:1:fileParts - 1
{
	set dirName = $PIECE(svnPath, "/", ind)
	set fullPath = fullPath _ "/" _ dirName
	if ( ' ##class(%Library.File).Exists(fullPath))
	{
		Do ##class(ITFCOMMON.Utility).WriteToFile("AddDirectoriesToSvn, create directory: " _fullPath)
		Do ##class(%File).CreateDirectory(fullPath)
	}
	Do ..AddToSvn(fullPath, 1, passwd)
}


	set tStatus = $$$ERROR(100, "Error in checkout")


	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		if ( fileNm '= "")
		{	 
			If ##class(%File).Exists(fileNm)
			{
	  			Do ##class(%File).Delete(fileNm)
			}	
			if (rev '= "")
			{
				Set cmd= $$$SVNUPDATE _ " --revision " _ rev
			}
			else
			{		
			  Set cmd= $$$SVNUPDATE 
			}
			Set cmd= cmd _ " --username " _ $username _ " --password " _ passwd _ " " _  fileNm 

			Set status = $ZF(-1, cmd)
			If ##class(%File).Exists(fileNm)
			{
	           Do ##class(ITFCOMMON.Utility).WriteToFile("File Exists, checkout: " _ fileNm _ ": " _ status)

         	   #; Call the function to do the load
         	   Set tStatus=$system.OBJ.Load(fileNm,"-l-d")
         	   if $$$ISOK(tStatus)
         	   { 
         		 Do ##class(ITFCOMMON.Utility).WriteToFile("OBJ.Loaded: " _ fileNm _ ": " _ status)
         		 set tStatus = $$$OK       
	  		   }
	  		   else
	  		   {
		  		   Set cmd= "cp " _ fileNm _ " /home/lpjnaras"
		  		   Set status = $ZF(-1, cmd)
		  		   Do ##class(ITFCOMMON.Utility).WriteToFile(cmd _ " " _ status)
	  		   }
			}
			else
			{
				Do ##class(ITFCOMMON.Utility).WriteToFile( $$$SVNUPDATE _ " failed: " _ fileNm)
				Quit $$$ERROR(6484, "Error in checked from subversion")
			}
		}
	}

	Quit tStatus


	set fileInfo = ""

	Do ##class(ITFCOMMON.Utility).WriteToFile("GetSvnInformation " _ $NAMESPACE _ " " _ $username)
	if (Selectedfiles = "")
	{
		Quit $$$ERROR(6484, "FileName")
	}
	For I=1:1:$L(Selectedfiles,",")
	{
		Set fileNm = $P(Selectedfiles,",",I)
		set tempFile = 	fileNm _ "Temp"
		if (##class(%File).Exists(tempFile) )
	  	{
			Do ##class(%Library.File).Delete(tempFile)
	  	}
		if ( (fileNm '= "") && (##class(%File).Exists(fileNm) ) )
		{	 


	         Set cmd= $$$SVNINFO _ fileNm _ " >> " _ tempFile

			 Set status = $ZF(-1, cmd)

	         Set cmd=  $$$SVNLOG _" --username " _ $username _ " --password " _ passwd _ " " _ fileNm _ " >> " _ tempFile 

			 Set status = $ZF(-1, cmd)

	  		if (##class(%File).Exists(tempFile) )
	  		{
         		#; Call the function to do the load
         		Set tStatus=..GetFileContent(tempFile) 
         		Set fileInfo = fileInfo _ tStatus       
	  		}
	  		else
	  		{
		  		SET fileInfo = "svn command failed: " _ cmd
	  		}
		}
	}
	Quit fileInfo

	set fullPath = $$$USRBASEDIR _ $username _ $$$SVNBASEDIR  _ $$$SVNTRUNK _ "cls/" _ $NAMESPACE
	set tempFile = $$$USRBASEDIR _ $username _ "/tempSvnList"
 	Set cmd = $$$SVNLIST _ " --username " _ $username _ " --password " _ passwd _ " " _ fullPath _ " > " _ tempFile
	Set stat = $ZF(-1, cmd)
	Do ##class(ITFCOMMON.Utility).WriteToFile( $$$SVNLIST _ ": " _ stat)

    Set filesList= ##class(%Library.ListOfDataTypes).%New()

     If ##class(%File).Exists(tempFile)
     {

		Set file=##class(%File).%New(tempFile)
		// Write !, "File size:" _ file.Size
		Do file.Open("RS")

    	While 'file.AtEnd 
    	{ 
     		set ln = file.ReadLine(,.sc,.eol) 
     		If $$$ISERR(sc) 
     		{ 
     			Do ##class(ITFCOMMON.Utility).WriteToFile( "ERROR reading file")
     			 Quit 
     			} 
     		elseIf eol 
     		{ 
     			Do ##class(ITFCOMMON.Utility).WriteToFile("EOF " _ eol)
     		} 
     		else
     		{
	    		Do ##class(ITFCOMMON.Utility).WriteToFile("File name: " _ ln)
	    		if ( $LENGTH(ln) > 1)
	    		{
		    		DO filesList.Insert( fullPath _ "/" _ ln)
	    		}
     		}
    	}
    	// Do file.close()
    	// Do file.Delete()
     }
  Do ##class(ITFCOMMON.Utility).WriteToFile("Number files in SVN list: " _ filesList.Count())
  Quit filesList

	#dim fileList as %Library.ListOfDataTypes
	 // Types of classes we need
	Set SrcCtrlList=$LB("Ens.BusinessProcessBPL", "Ens.Rule.Definition", "Ens.DataTransformDTL", 
   		"Ens.Rule.FunctionSet", "%Persistent", "%Studio.SourceControl.Base",
   		"%ZEN.application", "%ZEN.Component.page")

   	// Ignore classes that start with Intersystem class name	
    Set classesList=$LB("CSPX", "Ens", "EnsLib", "EnsPortal", "HS")



	set itNum = 0
	try
	{
		set fileList = ..GetFilesInSvn(passwd) 
		Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems " _ fileList.Count())
	  kill ^|"ITFCOMMON"|ItfSourceCtrl
	  Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems " _ $NAMESPACE _ " " _ $username)
	  IF $$$ISERR( ..CheckSvnSetup(passwd))
	  {
		  set tExp = ##class(%Exception.General).%New()
		  set tExp.Name = "Setup error"
		  set tExp.Code=999
		  set tExp.Location = "CheckSvnSetup"
		  set tExp.Data = "Check: " _ $$$USRBASEDIR _ $username
		  Throw tExp
	  }


     Set rset = ##class(%ResultSet).%New("%Dictionary.ClassDefinition:Summary")

     Do rset.Execute()


     While (rset.Next(.sc)) // next row of result set
     {
    	If ($SYSTEM.Status.IsOK(sc)) // check for errors
    	{
	    	 set clNm =  rset.Data("Name")
	    	//  Do ##class(ITFCOMMON.Utility).WriteToFile(clNm)
	    	 // Not a system class and does not start with %
          	 if ((rset.Data("System") = 0 ) && ( $Extract(clNm, 1,1) '= "%"))
             {
                set clType = $PIECE(clNm, ".", 1)
                // Not Inter systems class and is one of the classes defined above
                if ( (' $LF(classesList, clType)) && ($LF(SrcCtrlList, rset.Data("Super")) ) )
                {
	             Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems: " _ clNm _ " " _ rset.Data("Super"))
	              set stat =  ..AddToSourceControl(clNm _ ".CLS")	
	              if ( stat '= $$$OK)
	              {
		              Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems: AddToSourceControl returned error")
	                return 0
	              }

	              Set svnFile = ..ExternalName(clNm _ ".CLS")
	               Do ##class(ITFCOMMON.Utility).WriteToFile(svnFile _ " " _ fileList.Count())
	               set findInd = fileList.Find(svnFile)
	              if ( findInd )

                  {
	                   Do ##class(ITFCOMMON.Utility).WriteToFile( "Found in SVN List: " _ svnFile)
	                   Do fileList.RemoveAt(findInd)    
                  }
	              set itNum = itNum + 1
           	 }
        }
   	 }
    }
    Do ..AddSvnFilesToSourceControl(fileList)        
	Do ##class(ITFCOMMON.Utility).WriteToFile("GetItems: "_ itNum _ ", last item: " _ clNm)  
	} catch err
	{
		Do ##class(ITFCOMMON.Utility).WriteToFile("ERROR in GetItems: " _ err.Name _ " " _ err.Location)
		throw err
	}    
	Quit itNum


	 // check for the parent directory
	 SET usrBaseDir = $$$USRBASEDIR _ $username
	 Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup " _ usrBaseDir)

	 IF ' ##class(%File).DirectoryExists(usrBaseDir)
	 {
		 if $$$ISERR( ##class(%File).CreateDirectory(usrBaseDir))
		    Quit $$$ERROR(100, "User Home directory could not be created")
     }
     ELSE {
	     Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup " _ " User Home directory exists")
     }

     SET svnBaseDir = usrBaseDir _ $$$SVNBASEDIR
     Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup " _ svnBaseDir) 
	 IF ' ##class(%File).DirectoryExists(svnBaseDir)
     {
         Do ##class(%File).CreateDirectory(svnBaseDir)
	 }
	 ELSE {
	     Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup " _ svnBaseDir _ " User Home directory exists")
     }

     // Checkout complete tree
     SET svntrunk = svnBaseDir _ $$$SVNTRUNK
     Do ##class(ITFCOMMON.Utility).WriteToFile(svntrunk)
     IF ' ##class(%File).DirectoryExists("CheckSvnSetup " _svntrunk)
	 {
	   set svnCmd = $$$SVNCHECKOUT _ " --username " _ $username _ " --password " _ passwd _ " " _ $$$SVNURL _ " " _ svntrunk 
	   Set status = $ZF(-1, svnCmd)
	   Do ##class(ITFCOMMON.Utility).WriteToFile($$$SVNCHECKOUT _ " " _ status)
	 }
	 Do ##class(ITFCOMMON.Utility).WriteToFile("CheckSvnSetup: Exit ")
     Quit $$$OK

	set fileStamp = ""

	if (##class(%File).Exists(fileNm) )
	{
		set fTime = ##class(%File).GetFileDateModified(fileNm)
		set fileStamp = $ZDATETIME(fTime, 3, 1)

		// Get SVN output to a TEMP file
		set TempFile =  fileNm _ "tempFileSvn"
		set cmd = $$$SVNINFO _ fileNm _ " > " _ TempFile
		Set status = $ZF(-1, cmd)

		if (##class(%File).Exists(TempFile) )
		{
         Set fileObj=##class(%Library.File).%New(TempFile)
         Do fileObj.Open("RS") ; Read mode and as stream
         While 'fileObj.AtEnd 
         {
	        set reLn = fileObj.ReadLine(,.sc,.eol)
	        set dtTmInd = $F(reLn, $$$SVNCHECKINTIME)

	        if dtTmInd > 0
	        {
		        // find last time and strip spaces, Get date and time 
		        set tmPart = $ZSTRIP($Extract(reLn, dtTmInd, $Length(reLn)),"<>W")
	            set fileStamp = $Piece(tmPart, " ", 1) _ " " _ $Piece(tmPart, " ", 2)
	        }
         }
         Do fileObj.Close()
         Do ##class(%Library.File).Delete(TempFile)
       }

	}
	Do ##class(ITFCOMMON.Utility).WriteToFile("GetSvnTime: " _ fileNm _ " " _ fileStamp)
	Quit fileStamp

	Do ##class(ITFCOMMON.Utility).WriteToFile("Add SVN files: " _ fileList.Count())
	set key = fileList.Next("")
	  while(key >= 1)
	  {
		set file = fileList.GetAt(key)

	    set fileStamp = ..GetSvnTime(file)
        &sql(SELECT  FileName INTO :dbFile FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:file)
		if SQLCODE '= 0 {
	       &sql(INSERT INTO ITFCOMMON.SrcCtrlInfo SET FileModifiedTime=:fileStamp ,FileName=:file)
        }
         else
        {

	        &sql(UPDATE ITFCOMMON.SrcCtrlInfo SET FileModifiedTime=:fileStamp WHERE FileName=:file )
        }
        set key = fileList.Next(key)
	  }
	  Quit $$$OK


	set initCom=""
	set dbFile = ""
	Set file=..ExternalName(InternalName)

	set intTime= ##class(%RoutineMgr).TS(InternalName)
	set stat = $$$ERROR(100, "Can't add file to SourceControl")

	set fileStamp = ..GetSvnTime(file)
	Do ##class(ITFCOMMON.Utility).WriteToFile("AddToSourceControl: " _ $NAMESPACE _ " " _ $username _ " " _ file)

	if ( file '= "" )
	{
        Do ##class(ITFCOMMON.Utility).WriteToFile("Insert/Update ITFCOMMON.SrcCtrlInfo: " _ file )

		&sql(SELECT  FileName INTO :dbFile FROM ITFCOMMON.SrcCtrlInfo WHERE FileName=:file)
		if SQLCODE '= 0 {
	       &sql(INSERT INTO ITFCOMMON.SrcCtrlInfo SET InternalName = :InternalName ,FileName=:file,ClassModifiedTime=:intTime,FileModifiedTime=:fileStamp)
        }
        else
        {
	        // Write !, "file exists: " _ dbFile
	        &sql(UPDATE ITFCOMMON.SrcCtrlInfo SET ClassModifiedTime=:intTime,FileModifiedTime=:fileStamp WHERE FileName=:file )
        }
        IF SQLCODE '= 0 {
              Do ##class(ITFCOMMON.Utility).WriteToFile("Insert ITFCOMMON.SrcCtrlInfo failed " _ file _ " CODE: " _ SQLCODE _ " IntNm: " _ InternalName _ " intTime " _ intTime _ " :fileStamp" _ fileStamp)
        }
        else
        {
	           set stat = $$$OK
        }
	}

	Quit stat

// Write !, "Mapping Name"
// Do ##class(ITFCOMMON.Utility).WriteToFile("Name: " _ InternalName)
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 
{
	Set src = ..setSources()
	// Write !,"^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work"
	Set src = $data(^|"ITFCOMMON"|ItfSourceCtrl) 
	Do ##class(ITFCOMMON.Utility).WriteToFile( "Sources set: " _ src)
}	
If $data(^|"ITFCOMMON"|ItfSourceCtrl)'=11 
{
	Do ##class(ITFCOMMON.Utility).WriteToFile("^|""ITFCOMMON""|ItfSourceCtrl is not setup so hooks will not work" )
	Quit ""
}
// For an abstract document, use the GetOther() method to try to determine its "real" class
If ##class(%RoutineMgr).UserType(InternalName,.docclass,.doctype) {
	// Check for a real abstract document subclass (or GetOther() may not work)
	If $classmethod(docclass,"%IsA","%Studio.AbstractDocument") {
		// Grab the actual name
		Set actualName = $classmethod(docclass,"GetOther",InternalName)
		// The actualName is only valid if we get a single .cls as a result
		If actualName'[",",$ZCVT($P(actualName,".",$L(actualName,".")),"U")="CLS" {
			// We use what GetOther() gives us, thus Demo.Loan.FindRateProcess.bpl becomes Demo.Loan.FindRateProcess.cls
			Set InternalName = actualName
		}
	}
}	

If $$CheckProtect^%qccServer(InternalName) Quit ""
Set nam=$p(InternalName,".",1,$l(InternalName,".")-1),ext=$p(InternalName,".",$l(InternalName,".")),ext=$zcvt(ext,"u")
If nam="" Quit ""
If ext="PRJ",nam["Default_" Quit ""
If ext="CLS",$$$defClassKeyGet(nam,$$$cCLASSgeneratedby)'="" Quit ""
Set default=0
Set p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,nam)) For  s p=$order(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),-1) Quit:p=""  If $extract(nam,1,$length(p))=p,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,p),found) Quit
If $data(found)=0,$data(^|"ITFCOMMON"|ItfSourceCtrl(ext,"*"),found) Set default=1
If $data(found)=0 Quit ""
// Do ##class(ITFCOMMON.Utility).WriteToFile("found: " _ found)
If InternalName["/" {
	Set InternalName=$extract(InternalName,$length(p)+1,*)
	Set extNm = $translate(found_$translate(InternalName,"%","_"),"\","/")
	Quit extNm
}
If ext="CLS"||(ext="PRJ")||(##class(%RoutineMgr).UserType(InternalName))
{ 
   set extNm = $translate(found_$translate(nam,".%","/")_".xml","\","/")
   Quit extNm
}
set extNm = $translate($g(found)_$tr(nam,"%"_$s(default:".",1:""),"_/")_".xml","\","/")
Quit extNm
